// Pega os dados do primeiro input
const data = $input.first().json;

// Verifica se é um array; se não for, transforma em um
const estados = Array.isArray(data) ? data : [data];

// Pega o nome do estado vindo do outro nó ("RD")
const estado = $('RD').first().json.Estado;

// Busca o item que corresponde ao estado
const encontrado = estados.find(e => e.Name === estado);

// Retorna apenas 1 resultado (o ID) ou null
return [{ json: { Id: encontrado ? encontrado.Id : null } }];
